// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Call setOwner through the onlyAdmin modifier (admin is deployer = address(this))
        // The reference sets owner = _owner, mutant sets owner = address(0)
        c.setOwner(_owner);
        // General rule: after setOwner, c.owner() should equal _owner
        assertTrue(c.owner() == _owner);
    }
}

